// Extract custom fields from ClickUp task
const task = $input.first().json;
const customFields = task.custom_fields || [];

function getField(name) {
  const field = customFields.find(f => f.name === name);
  return field ? field.value : null;
}

function getLabelsField(name) {
  const field = customFields.find(f => f.name === name);
  if (!field || !field.value) return [];
  if (Array.isArray(field.value)) {
    return field.value.map(v => typeof v === 'string' ? v : v.label || v.name || '');
  }
  return [];
}

const taskData = {
  taskId: task.id,
  taskName: task.name,
  kundenName: getField('Kundenname') || task.name,
  ansprechpartner: getField('Ansprechpartner') || '',
  email: getField('E-Mail') || '',
  services: getLabelsField('Services'),
  branche: getField('Branche') || 'Other',
  projektBeschreibung: getField('Projektbeschreibung') || '',
  budget: getField('Budget') || '10-20k',
  timeline: getField('Timeline') || '3-6 Monate',
  sprache: getField('Sprache') || 'DE',
  bestehenderKunde: getField('Bestandskunde') === true,
  notizen: getField('Notizen') || ''
};

// Validate required fields
const required = ['kundenName', 'ansprechpartner', 'email', 'projektBeschreibung'];
const missing = required.filter(f => !taskData[f]);

if (taskData.services.length === 0) missing.push('services');

return [{
  json: {
    taskData,
    isValid: missing.length === 0,
    missingFields: missing
  }
}];

// Assemble the proposal document content
const taskData = $('Parse Custom Fields').item.json.taskData;
const aiResponse = JSON.parse($input.first().json.message.content);

const docTitle = `Angebot_${taskData.kundenName.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}`;

// Build document body
let body = '';

// Page 1: Cover Letter
body += aiResponse.coverLetter.greeting + '\n\n';
body += aiResponse.coverLetter.body + '\n\n';
body += aiResponse.coverLetter.closing + '\n\n';
body += '---\n\n';

// Page 2: Legal Notice
body += 'Rechtlicher Hinweis\n\n';
body += 'Dieses Angebot ist 6 Wochen ab Erhalt gültig.\n';
body += 'Es gelten die AGB der zukunvt GmbH.\n\n';
body += '---\n\n';

// Page 3: Calculation
body += 'Kalkulation\n\n';
if (aiResponse.calculationDescriptions) {
  aiResponse.calculationDescriptions.forEach((phase, i) => {
    body += `${i + 1}. ${phase.phaseTitle}\n`;
    body += `Fokuspunkte: ${phase.fokuspunkte.join(', ')}\n`;
    body += `Inhalt: ${phase.inhalt.join(', ')}\n`;
    body += `Phasenziel: ${phase.phasenziel}\n`;
    body += `Output: ${phase.output.join(', ')}\n\n`;
  });
}
body += '---\n\n';

// Page 4: Summary
body += 'Zusammenfassung & Konditionen\n\n';
body += `Inkludiert: ${aiResponse.inclusions.join(', ')}\n`;
body += `Exkludiert: ${aiResponse.exclusions.join(', ')}\n\n';
body += '---\n\n';

// Page 5: References
body += 'Partner-Referenzen\n\n';
if (aiResponse.references) {
  aiResponse.references.forEach(ref => {
    body += `${ref.partnerName} — ${ref.industry}\n`;
    body += `${ref.description}\n\n`;
  });
}
body += '\npartner.zukunvt.it';

return [{
  json: {
    docTitle,
    docBody: body,
    taskId: taskData.taskId
  }
}];
